-- =====================================================================
-- TÉCNICA · FASE 1 · CORTE 15 · «EVENTO DE SUSPENSIÓN» · 05 — HUELLAS DE SOLO LECTURA (una sola consulta; apta para el editor SQL web). No escribe nada.
-- ANTES: «funciones de redes» dice «CORRECCIÓN DEL 9b (lista para el 15)», tecnica.f_avisos «LA DEL CORTE 14», las 33 nuevas «NO EXISTE» y las tablas «NO EXISTEN».
-- DESPUÉS: «CORTE 15 (aplicado)», f_avisos «CORTE 15 (reemplazada)», 33 «NUEVA» y las tablas «EXISTEN». Cualquier «DISTINTA» o «FALTA»: no aplique nada y avise.
-- Las huellas de tecnica.f_avisos salen de la base local de Code A (no se han comprobado contra la base viva): por eso van aquí, antes de todo.
-- =====================================================================
with nue(firma, nueva) as (values ('public.geoportal_redes_evento(text,text)', '731d53c3738c82927ffc429fbc9df72e'), ('public.geoportal_redes_evento_anular(text,text,text)', '8947de32c9f76c9bfc937a31e8bf2c39'), ('public.geoportal_redes_evento_asociar(text,text,text,text,text)', 'fe1d68797bafff55cd4c1546f19fd861'), ('public.geoportal_redes_evento_catalogo(text)', '129674a1c44946f4c81bcff95b595353'), ('public.geoportal_redes_evento_cerrar(text,text,text,text)', '1895de6b291861a6cc2d6072c95978b2'), ('public.geoportal_redes_evento_declarar(text,jsonb)', '03f66c04c76a2d9c2df0348c671b963a'), ('public.geoportal_redes_evento_desasociar(text,text,text,text,text)', '1b7294b2393c5b7003093414ecdcf230'), ('public.geoportal_redes_evento_regreso(text,text,text,text)', 'daa542d7d0b0f8cbb09c4f4429fbfd6a'), ('public.geoportal_redes_evento_tipo_fijar(text,text,text,boolean,text,text,text)', '79cc25576f325459a6c6e46f9bfde1eb'), ('public.geoportal_redes_evento_vista_previa(text,jsonb)', 'c5dcdc68f33cd2953fd7578018456a29'), ('public.geoportal_redes_eventos(text,text,integer)', '5b6e1f23c3985e69cfe4908dc3752b8a'), ('public.geoportal_redes_eventos_vigentes(text)', '30d3b3306038af969a1e7e1b75e6f5ef'), ('public.geoportal_redes_planta_sectores_fijar(text,text,text[],text)', '4446a2f9bf36d700330c0c2062a2bc9f'), ('redes.f_evento_abierto(text,text,text)', '59df33f21167b73cbc9a5049b505859e'), ('redes.f_evento_autorizar(text,text)', '1c1dc3406cf363dbe6c7a6de06e12954'), ('redes.f_evento_candidatos(geometry,boolean,timestamp with time zone,uuid)', '8f4fb54a89d2ea0b73cf8adf60e731b7'), ('redes.f_evento_clave(text)', '7c6a003aa4606fc55118d51d9e68dd44'), ('redes.f_evento_contratos(geometry,boolean,boolean)', '8dafa57412c9b41aca0a0e3652f3bf2a'), ('redes.f_evento_franja(text,timestamp with time zone,text,timestamp with time zone)', 'fb9de8c4ada4a35de44889aea9f17b62'), ('redes.f_evento_hora(timestamp with time zone)', '12bbc8120d7c066ab5ef5ec9b52d92d0'), ('redes.f_evento_json(bigint,boolean)', 'fe4f63968ba5247baf3faadb3ac0c8ed'), ('redes.f_evento_marcar(bigint[],text,text,text)', '1afbaaa2ee2ad4168f74b673c02b60c4'), ('redes.f_evento_ref_libre(text,text)', '2f1a58f701a1c3ffb1ff029c7e2bf755'), ('redes.f_evento_reporte_ref(text,text)', 'c1b76d3cefd7d9590388b0716f1dbcdf'), ('redes.f_evento_reportes(bigint)', 'e9d6c5b2d72868e188e2bc5eeda47ddd'), ('redes.f_evento_tg_bot()', 'a74767243451e7c5cc9f2d70bb040669'), ('redes.f_evento_tg_dano()', 'a802585704c230716634b759cf24eaae'), ('redes.f_evento_tg_l116()', 'd0303bbc84351a77c7e9b523219b9671'), ('redes.f_evento_zona(jsonb)', '71f7f27f97954858a61fcfab9f6a692f'), ('redes.f_eventos_abiertos()', '2d265a26461ea19a01e9a81bb927b120'), ('redes.f_eventos_para_avisos(timestamp with time zone)', '6dfe4fa606e840b59f3f465ea8849184'), ('redes.f_reporte_externo_recibir_evento(jsonb)', '92be46589b80d60ce38139e3fe44550d'), ('redes.f_sin_agua_para_avisos(timestamp with time zone,numeric)', '20930e1e1bd12a3fb01a835ba658b006')),
pub(firma, publicada) as (values ('redes.f_reporte_externo_recibir(jsonb)', '0c37fea57363e5bdd4624438c8803398'), ('redes.f_publicar_l116(bigint,text,text)', '1d70c1fe36186cf498504898e5098b64'), ('public.geoportal_redes_crear_dano(text,uuid,jsonb,text)', 'f6578d1011d2ccb8431881ab576a4a6b'), ('public.geoportal_redes_cortes_vigentes(text)', 'c09eadccc9399bb27b78dfb0ad14c8f8'), ('redes.f_sector_de(geometry)', '455378c9b8cf43343ff821a2896eae37')),
conj as (
  select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname)) as m from pg_proc p
   where p.pronamespace = 'redes'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_redes\_%'))
select '0 funciones de redes (conjunto)' as objeto, (select m from conj) as md5,
       case (select m from conj) when '63d917635b33e3696f28a3b0e579c002' then 'CORRECCIÓN DEL 9b (lista para el 15)' when 'aa7f80d7e0a3df7715474318650a5ec0' then 'CORTE 15 (aplicado)' else 'DISTINTA' end as estado
union all select '1 tecnica.f_avisos(boolean,boolean,timestamptz)', md5(pg_get_functiondef('tecnica.f_avisos(boolean,boolean,timestamptz)'::regprocedure)),
       case md5(pg_get_functiondef('tecnica.f_avisos(boolean,boolean,timestamptz)'::regprocedure)) when 'b7ec2303f95153684963ded7bdb0a5c0' then 'LA DEL CORTE 14' when '3c6b6143a3f6d48c5624ec3fe94fd324' then 'CORTE 15 (reemplazada)' else 'DISTINTA' end
union all select '2 ' || p.firma || ' (no se toca)', md5(pg_get_functiondef(to_regprocedure(p.firma))),
       case when to_regprocedure(p.firma) is null then 'FALTA' when md5(pg_get_functiondef(to_regprocedure(p.firma))) = p.publicada then 'LA PUBLICADA' else 'DISTINTA' end from pub p
union all select '3 ' || n.firma, md5(pg_get_functiondef(to_regprocedure(n.firma))),
       case when to_regprocedure(n.firma) is null then 'NO EXISTE (sin aplicar)' when md5(pg_get_functiondef(to_regprocedure(n.firma))) = n.nueva then 'NUEVA (aplicada)' else 'DISTINTA' end from nue n
union all select '4 tablas del corte (7)', null,
       case (select count(*) from pg_class c where c.relnamespace = 'redes'::regnamespace and c.relkind = 'r' and c.relname in ('eventos_suspension', 'evento_suspension_eventos',
               'evento_suspension_reportes', 'evento_tipos_asociables', 'evento_tipo_eventos', 'planta_sectores', 'planta_sector_eventos')) when 0 then 'NO EXISTEN (sin aplicar)' when 7 then 'EXISTEN' else 'FALTA' end
union all select '5 tablas que usa (bot, línea 116, daños, sensibles, plantas, catálogo de campo)', null,
       case when to_regclass('redes.reporte_externo_eventos') is not null and to_regclass('redes.l116_eventos') is not null and to_regclass('redes.l116_vigente') is not null
             and to_regclass('redes.danos') is not null and to_regclass('redes.usuarios_sensibles') is not null and to_regclass('tecnica.plantas') is not null
             and to_regclass('campo.tipos_reporte') is not null and exists (select 1 from campo.grupos_reporte where codigo = 'red_acueducto') then 'ESTÁN' else 'FALTA' end
union all select '6 INFO sectores y subsectores vigentes · plantas activas · sensibles confirmados · contratos con tramo', null,
       (select count(*) from redes.activo_vigente_mat where prefijo = 'SEC' and not retirado and not oculto) || ' · ' || (select count(*) from tecnica.plantas where activa)
       || ' · ' || (select count(*) from redes.v_usuario_sensible where estado = 'confirmado') || ' · ' || (select count(*) from redes.contrato_tramo)
union all select '7 INFO tipo «sin_agua» en el catálogo de campo · tipos parecidos', null,
       coalesce((select string_agg(t.codigo || '=' || t.nombre || case when t.activo then '' else ' (inactivo)' end, ' | ' order by t.codigo) from campo.tipos_reporte t
                  where t.codigo = 'sin_agua' or lower(t.nombre) like '%sin agua%' or lower(t.nombre) like '%no tengo agua%' or lower(t.nombre) like '%presi_n%'), 'ninguno')
union all select '8 INFO causales de acueducto de la línea 116 (para revisar la lista de lo que se asocia)', null,
       coalesce((select string_agg(x.causal || ' (' || x.n || ')', ' | ' order by x.n desc) from (select v.causal, count(*) n from redes.l116_vigente v where lower(v.servicio) = 'acueducto' group by 1) x), 'sin reportes')
order by 1;
